package com.example.domain.model.i18n

internal object DuaPt3 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_adhan_response" to DuaText("Responder ao Adhan", "Não há força nem poder senão em Allah.", "Repetir o que o muadhin diz; em 'Hayya 'alas-salah' e 'Hayya 'alal-falah' dizer esta frase.", "Quem responde do fundo do coração entrará no Paraíso."),
        "dua_adhan_shahadah" to DuaText("Após o testemunho do muadhin", "E eu também testemunho que não há divindade digna de adoração senão Allah, Único, sem associado, e que Muhammad ﷺ é Seu servo e Mensageiro. Estou satisfeito com Allah como Senhor, com Muhammad ﷺ como Mensageiro e com o Islã como religião.", "Ao ouvir o testemunho de fé do muadhin.", "Seus pecados são perdoados."),
        "dua_after_rain" to DuaText("Depois da chuva", "Recebemos chuva pela graça de Allah e Sua misericórdia.", "Depois da chuva.", "Quem diz isso é um crente em Allah."),
        "dua_after_witr" to DuaText("Depois do Witr", "Glória ao Rei, o Santíssimo.", "Três vezes após a saudação do witr, elevando a voz na terceira vez.", "O Profeta ﷺ dizia isso após o witr."),
        "dua_against_enemy_ahzab" to DuaText("Contra os exércitos inimigos", "Ó Allah, Revelador do Livro, Rápido em ajustar contas! Derrota os coligados. Ó Allah, derrota-os e abala-os.", "Contra o inimigo — a súplica da batalha dos Coligados.", "A súplica do Profeta ﷺ contra o inimigo."),
        "dua_ahsin_aqibatana" to DuaText("Torna boa a nossa conclusão em toda situação", "Ó Allah, torna boa a nossa conclusão em toda situação, e protege-nos da desonra nesta vida e do castigo na Outra.", "Para uma boa conclusão em toda coisa.", "Quem faz esta súplica e morre antes de ser provado, morre a salvo da provação."),
        "dua_ahyini_ma_kanat" to DuaText("Em vez de desejar a morte", "Ó Allah, faze-me viver enquanto a vida for melhor para mim, e leva-me quando a morte for melhor para mim.", "Em vez de desejar a morte na aflição.", "O Profeta ﷺ proibiu desejar a morte e ensinou isto em seu lugar."),
        "dua_ajz_kasal_haram" to DuaText("Refúgio contra a incapacidade e a velhice", "Ó Allah, busco refúgio em Ti contra a incapacidade e a preguiça, a covardia e a velhice, as provações da vida e da morte, e o castigo da sepultura.", "Uma súplica diária completa de proteção.", "Uma súplica que o Profeta ﷺ fazia frequentemente."),
        "dua_ala_kulli_hal" to DuaText("Louvor em toda situação", "Louvado seja Allah em toda situação.", "Quando acontece algo desagradável.", "O Profeta ﷺ dizia isso diante do que não gostava."),
        "dua_alimal_ghayb" to DuaText("Conhecedor do invisível", "Ó Allah, Conhecedor do invisível e do visível, Criador dos céus e da terra, Senhor e Soberano de todas as coisas! Testemunho que não há divindade senão Tu. Busco refúgio em Ti contra o mal da minha alma, e contra o mal de Satanás e seu apelo ao shirk.", "De manhã, à noite e antes de dormir — o Profeta ﷺ ensinou isso a Abu Bakr (RA).", "Proteção contra o mal da alma e de Satanás."),
        "dua_allahu_akbar_kabira_2696" to DuaText("Palavras ensinadas a um beduíno", "Não há divindade digna de adoração senão Allah, Único, sem associado. Allah é o Maior, grandemente; abundante louvor a Allah; glória a Allah, Senhor dos mundos; e não há força nem poder senão em Allah, o Todo-Poderoso, o Sábio.", "Uma fórmula completa de dhikr e súplica — ensinada a um beduíno.", "Depois disso, ensinaram-lhe a dizer 'Allahummaghfir li warhamni wahdini warzuqni'."),
        "dua_allahu_rabbi" to DuaText("Allah, Allah é meu Senhor", "Allah, Allah é meu Senhor; não Lhe associo nada.", "Na aflição ou angústia — o Profeta ﷺ ensinou isso a Asma bint Umays (RA).", "Apegar-se ao tawhid nos momentos de angústia."),
        "dua_amsayna_fitrah" to DuaText("À noite sobre a fitra do Islã", "Anoitecemos sobre a fitra do Islã, sobre a palavra da sinceridade, sobre a religião do nosso Profeta Muhammad ﷺ e sobre o caminho do nosso pai Ibrahim (AS), que era reto e muçulmano, e não era dos idólatras.", "À noite.", "Renovar a fé toda noite."),
        "dua_anta_adudi" to DuaText("Tu és meu apoio", "Ó Allah, Tu és meu apoio e meu socorro. Por Ti eu manobro, por Ti avanço e por Ti combato.", "Antes de uma competição ou grande provação.", "O Profeta ﷺ dizia isso no combate."),
        "dua_arafah" to DuaText("A melhor súplica do dia de Arafah", "Não há divindade digna de adoração senão Allah, Único, sem associado. D'Ele é o domínio, a Ele pertence o louvor, e Ele é capaz de todas as coisas.", "O dia de Arafah — a melhor súplica.", "A melhor súplica é a do dia de Arafah, e as melhores palavras são estas."),
        "dua_ascending_descending" to DuaText("Ao subir e descer", "Allah é o Maior (ao subir). — Glória a Allah (ao descer).", "Em viagem, dizer 'Allahu Akbar' ao subir e 'SubhanAllah' ao descer.", "A prática dos Companheiros (RA) em viagem."),
        "dua_aslih_li_dini" to DuaText("Corrige minha religião, este mundo e o além", "Ó Allah, corrige minha religião, que é a salvaguarda de todos os meus assuntos; corrige minha vida terrena, onde está meu sustento; e corrige meu além, para onde retornarei. Faze da vida um acréscimo de bem para mim, e faze da morte um alívio para mim de todo mal.", "Corrigir a religião, este mundo e o além, todos os três.", "Uma súplica completa do Profeta ﷺ."),
        "dua_ati_nafsi_taqwaha" to DuaText("Concede à minha alma sua piedade", "Ó Allah, concede à minha alma sua piedade e purifica-a, pois Tu és o melhor para purificá-la. Tu és seu Protetor e seu Senhor.", "Para corrigir e purificar a alma.", "O Profeta ﷺ fazia frequentemente esta súplica."),
        "dua_ayyub" to DuaText("Súplica de Ayyub (AS) na doença", "(Meu Senhor,) a desgraça me atingiu, e Tu és o mais Misericordioso dos misericordiosos.", "Em caso de doença e sofrimento.", "Allah dissipou a provação de Ayyub (AS)."),
        "dua_bad_character" to DuaText("Refúgio contra o mau caráter", "Ó Allah, busco refúgio em Ti contra o mau caráter, as más ações e os maus desejos.", "Proteção contra o mau caráter, atos e desejos.", "Uma súplica de proteção do Profeta ﷺ."),
        "dua_being_praised" to DuaText("Quando se é elogiado", "Ó Allah, não me responsabilizes pelo que dizem, e perdoa-me o que não sabem.", "Ao ouvir elogios — a prática de um Companheiro (RA).", "Uma forma de evitar o orgulho quando se é elogiado."),
        "dua_beneficial_knowledge" to DuaText("Conhecimento útil e sustento lícito", "Ó Allah, peço-Te conhecimento útil, sustento puro e obras aceitas.", "Depois da oração do Fajr.", "O Profeta ﷺ dizia isso após a saudação do Fajr."),
        "dua_bi_ilmikal_ghayb" to DuaText("Faze-me viver enquanto a vida for um bem", "Ó Allah, por Teu conhecimento do invisível e Teu poder sobre a criação — faze-me viver enquanto souberes que a vida é melhor para mim, e leva-me quando souberes que a morte é melhor para mim. Ó Allah, peço-Te temer-Te em privado e em público, a palavra da verdade no contentamento e na ira, e a moderação na pobreza e na riqueza.", "A súplica de oração de Ammar ibn Yasir (RA) (primeira parte).", "O Profeta ﷺ fazia esta súplica na oração."),
        "dua_closing_eyes" to DuaText("Ao fechar os olhos do falecido", "Ó Allah, perdoa a (nome), eleva seu grau entre os bem guiados, sê seu substituto entre os que ele deixou para trás. Perdoa-nos e a ele, ó Senhor dos mundos; alarga sua sepultura e enche-a de luz.", "Ao fechar os olhos do falecido (mencionando seu nome).", "O Profeta ﷺ fez essa súplica por Abu Salama (RA)."),
        "dua_condolence" to DuaText("Condolências (Ta'ziyah)", "O que Ele tomou pertence a Allah, e o que Ele deu também Lhe pertence, e toda coisa tem junto a Ele um prazo determinado; sê, pois, paciente e espera a recompensa.", "Apresentar condolências a uma família após um falecimento.", "O Profeta ﷺ enviou esta mensagem à sua filha."),
        "dua_dogs_barking" to DuaText("Latidos de cães à noite", "Busco refúgio em Allah contra Satanás, o amaldiçoado.", "Ao ouvir cães latindo ou um burro zurrando à noite.", "Eles veem o que vocês não veem."),
        "dua_dressing" to DuaText("Ao se vestir", "Louvado seja Allah, que me vestiu com isto e mo concedeu sem força nem poder de minha parte.", "Ao se vestir.", "Anúncio do perdão dos pecados passados."),
        "dua_eid_greeting" to DuaText("A saudação do Eid", "Que Allah aceite (as boas obras) de nós e de vós.", "A ser dita mutuamente no dia do Eid — prática dos nobres Companheiros (RA).", "Os Companheiros diziam isso ao se encontrarem no dia do Eid."),
        "dua_eid_takbeer" to DuaText("O Takbir a caminho do Eid", "Allah é o Maior, Allah é o Maior, não há divindade senão Allah, e Allah é o Maior, Allah é o Maior, e a Allah o louvor.", "Desde a noite do crescente até a oração do Eid al-Fitr, especialmente a caminho do local da oração.", "O mandamento alcorânico: 'para que completeis o número e proclameis a grandeza de Allah' (Al-Baqarah 2:185). Ibn Mas'ud (RA) dizia este takbir."),
        "dua_entering_village" to DuaText("Ao entrar em uma cidade ou vila", "Ó Allah, Senhor dos sete céus e do que eles cobrem com sombra, Senhor das sete terras e do que elas carregam, Senhor dos demônios e de quem eles desviam, Senhor dos ventos e do que eles dispersam! Pedimos-Te o bem desta cidade e o bem de seus habitantes, e buscamos refúgio em Ti contra seu mal, o mal de seus habitantes e o mal do que nela existe.", "Antes de entrar em uma cidade.", "O Profeta ﷺ recitava isso sempre que queria entrar em uma cidade."),
        "dua_evening_blessing" to DuaText("Gratidão da noite pelos favores", "Ó Allah, todo favor que eu ou qualquer uma de Tuas criaturas recebemos nesta noite vem de Ti só, sem associado; a Ti, pois, todo o louvor e todo o agradecimento.", "Dhikr noturno de gratidão pelos favores de Allah.", "Reconhecer que todo bem vem exclusivamente de Allah."),
        "dua_evening_witness" to DuaText("Testemunho da noite sobre o tawhid", "Ó Allah, entro na noite tomando-Te, os portadores de Teu Trono, Teus anjos e toda a Tua criação como testemunhas de que Tu és Allah, não há divindade senão Tu, Único, sem associado, e que Muhammad ﷺ é Teu servo e Mensageiro.", "A narração menciona dizer isso quatro vezes à noite.", "Quem o disser, Allah o libertará de uma parte do Fogo."),
        "dua_fadlika_wa_rahmatik" to DuaText("Peço-Te de Tua graça e de Tua misericórdia", "Ó Allah, peço-Te de Tua graça e de Tua misericórdia, pois ninguém as possui senão Tu.", "Ao pedir sustento e misericórdia.", "Convidados vieram à casa do Profeta ﷺ quando não havia comida; ele fez esta súplica, e um presente chegou."),
        "dua_faqr_qillah_dhillah" to DuaText("Refúgio contra a pobreza e a humilhação", "Ó Allah, busco refúgio em Ti contra a pobreza, a escassez e a humilhação, e contra fazer mal ou sofrê-lo.", "Para ser preservado da precariedade, da necessidade e da humilhação.", "Um refúgio ensinado pelo Profeta ﷺ."),
        "dua_fasting_invited" to DuaText("Quando convidado enquanto jejua", "Estou jejuando.", "Quando convidado enquanto jejua, ou quando alguém o provoca.", "Se o jejuador aceita um convite, deve suplicar por seu anfitrião."),
        "dua_fear_people" to DuaText("Temor de inimigos ou opressores", "Ó Allah, colocamo-Te diante deles e buscamos refúgio em Ti contra o mal deles.", "Quando se teme o mal de um povo ou pessoa.", "O Profeta ﷺ dizia isso quando temia um povo."),
        "dua_filal_khayrat" to DuaText("Fazer o bem e evitar o mal", "Ó Allah, permite-me fazer boas ações, evitar más ações e amar os pobres, e perdoa-me e tem misericórdia de mim. E quando quiseres provar um povo, leva-me sem ser provado. Peço-Te Teu amor, o amor de quem Te ama, e o amor das ações que me aproximam de Teu amor.", "Allah ensinou esta súplica ao Profeta ﷺ em sonho.", "O Profeta ﷺ disse: ela é verdadeira, aprendam-na e ensinem-na."),
        "dua_fitnat_ghina_faqr" to DuaText("Refúgio contra as provações da riqueza e da pobreza", "Ó Allah, busco refúgio em Ti contra a preguiça e a velhice, o pecado e a dívida, a provação e o castigo da sepultura, a provação e o castigo do Fogo, o mal da provação da riqueza, e a provação da pobreza.", "Proteção contra as provações da sepultura, do Inferno, da riqueza e da pobreza (parte da súplica).", "Uma súplica completa de proteção do Profeta ﷺ."),
        "dua_fitratil_islam" to DuaText("Sobre a fitra do Islã", "Amanhecemos sobre a fitra do Islã, sobre a palavra da sinceridade, sobre a religião do nosso Profeta Muhammad ﷺ e sobre o caminho do nosso pai Ibrahim (AS), que era reto e muçulmano, e não era dos idólatras.", "De manhã.", "Renovar a fé todas as manhãs."),
        "dua_five_things_new_muslim" to DuaText("Perdoa, tem misericórdia, guia, preserva, sustenta", "Ó Allah, perdoa-me, tem misericórdia de mim, guia-me, concede-me o bem-estar e provê minhas necessidades.", "O Profeta ﷺ ensinava esta súplica, junto com a oração, aos novos muçulmanos.", "O Profeta ﷺ disse: estas palavras reúnem para ti este mundo e o além."),
        "dua_for_one_i_cursed" to DuaText("Por alguém que magoei com minhas palavras", "Ó Allah, todo crente que insultei, faze disso para ele um meio de aproximação a Ti no Dia da Ressurreição.", "Para alguém a quem se falou mal com raiva.", "Uma súplica do Profeta ﷺ."),
        "dua_for_who_gave_drink" to DuaText("Por quem me deu de beber", "Ó Allah, alimenta quem me alimentou e dá de beber a quem me deu de beber.", "Para quem lhe oferece comida ou bebida.", "O Profeta ﷺ fez esta súplica por al-Miqdad (RA)."),
        "dua_four_beloved_words" to DuaText("As quatro palavras mais amadas", "Glória a Allah, louvor a Allah, não há divindade senão Allah, e Allah é o Maior.", "As palavras mais amadas por Allah.", "São mais queridas ao Profeta ﷺ do que tudo sobre o que o sol nasce."),
        "dua_ghalabatid_dayn" to DuaText("Refúgio contra o peso da dívida", "Ó Allah, busco refúgio em Ti contra ser sobrecarregado pela dívida, dominado por um inimigo, e o escárnio dos inimigos.", "Proteção contra o peso da dívida e o domínio dos inimigos.", "O Profeta ﷺ buscava refúgio contra essas coisas."),
        "dua_going_to_mosque_nur" to DuaText("Ao se dirigir à mesquita (súplica da luz)", "Ó Allah, coloca luz em meu coração, luz em meus olhos, luz em meus ouvidos, luz à minha direita, luz à minha esquerda, luz acima de mim, luz abaixo de mim, luz à minha frente, luz atrás de mim, e faze de mim uma luz.", "Ao se dirigir à mesquita para o Fajr.", "O Profeta ﷺ a recitava ao sair para a oração."),
        "dua_hadm_gharaq" to DuaText("Refúgio contra acidentes e uma morte ruim", "Ó Allah, busco refúgio em Ti contra ser esmagado (sob um edifício), cair de uma altura, afogar-me, queimar-me e a velhice; contra Satanás me desviar no momento da morte, morrer fugindo de Teu caminho, e morrer de uma picada (venenosa).", "Proteção contra acidentes e uma morte ruim.", "Uma súplica de proteção do Profeta ﷺ."),
        "dua_hajj_la_riya" to DuaText("Um Hajj sem ostentação", "Ó Allah, (faze que seja) um Hajj sem ostentação nem busca de fama.", "Pela sinceridade ao formular a intenção do Hajj.", "O Profeta ﷺ fez esta súplica no momento do Hajj."),
        "dua_hamdan_kathiran" to DuaText("Abundante louvor após o ruku", "Nosso Senhor, a Ti pertence o louvor — abundante, puro e bendito.", "Ao se levantar do ruku, com 'Rabbana lakal-hamd'.", "Mais de trinta anjos se apressavam para ser o primeiro a escrevê-lo."),
        "dua_heavy_rain" to DuaText("Chuva excessiva", "Ó Allah, (faze-a cair) ao nosso redor e não sobre nós.", "Quando a chuva é excessiva.", "As nuvens se dissiparam graças à súplica do Profeta ﷺ."),
        "dua_hubbaka" to DuaText("Pedido do amor de Allah", "Ó Allah, peço-Te Teu amor, o amor de quem Te ama, e as ações que me aproximam de Teu amor. Ó Allah, torna Teu amor mais querido para mim do que eu mesmo, minha família e a água fresca.", "A súplica de Dawud (AS) relatada pelo Profeta ﷺ.", "O amor de Allah é a maior riqueza."),
        "dua_huda_tuqa" to DuaText("Orientação, piedade, castidade e suficiência", "Ó Allah, peço-Te orientação, piedade, castidade e suficiência.", "Uma súplica curta e completa do Profeta ﷺ.", "Quatro bênçãos fundamentais para a religião e este mundo."),
        "dua_husn_khatimah" to DuaText("Morrer como muçulmano (Yusuf AS)", "Criador dos céus e da terra, Tu és meu Protetor nesta vida e na próxima. Faze-me morrer submisso e junta-me aos virtuosos.", "Súplica por um bom fim.", "A súplica do profeta Yusuf (AS)."),
        "dua_iftar_ibn_umar" to DuaText("No iftar — Por Tua vasta misericórdia", "Ó Allah, peço-Te, por Tua misericórdia que abrange todas as coisas, que me perdoes.", "No iftar — Abdullah ibn Amr (RA) fazia esta súplica; a súplica do jejuador no iftar não é rejeitada.", "Hadith: a súplica do jejuador no momento do iftar não é rejeitada."),
        "dua_iftar_laka_sumtu" to DuaText("Ao romper o jejum — Para Ti jejuei", "Ó Allah, é para Ti que jejuei e é de Teu sustento que rompo meu jejum.", "Ao romper o jejum (a conhecida súplica do iftar).", "O Profeta ﷺ dizia isso no iftar. É uma narração mursal reforçada por outras; recitá-la no iftar é a prática dos Hanafitas e da maioria."),
        "dua_ihdini_saddidni" to DuaText("Guia-me e mantém-me reto", "Ó Allah, guia-me e mantém-me no caminho reto.", "O Profeta ﷺ ensinou isso a Ali (RA).", "Considerar a orientação como um caminho seguido, e a retidão como a exatidão de uma flecha."),
        "dua_ikfinihim" to DuaText("Basta-me contra eles", "Ó Allah, basta-me contra eles como Tu quiseres.", "Contra o mal dos opressores — a súplica do jovem na história dos Homens da Vala.", "Allah salvou o rapaz dos opressores."),
        "dua_ilbas_jadidan" to DuaText("Ao ver alguém com roupas novas", "Veste roupas novas, vive como homem louvado e morre como mártir.", "Ao ver um irmão muçulmano com roupas novas.", "O Profeta ﷺ fez esta súplica ao ver Umar (RA) com roupas novas."),
        "dua_infani_bima_allamtani" to DuaText("Faze-me aproveitar o que me ensinaste", "Ó Allah, faze-me aproveitar o que me ensinaste, ensina-me o que me será útil, e aumenta meu conhecimento.", "Ao buscar conhecimento ou antes de estudar.", "Uma súplica por conhecimento útil e por agir de acordo."),
        "dua_inni_saim" to DuaText("Quando provocado enquanto jejua", "Estou jejuando, estou jejuando.", "Quando alguém o insulta ou o provoca enquanto jejua.", "O Profeta ﷺ disse: o jejum é um escudo, o jejuador não deve, pois, proferir palavras obscenas nem agir com ignorância — se alguém o provocar, dizer isso duas vezes."),
        "dua_iqsim_lana_khashyatik" to DuaText("Concede-nos temor suficiente de Ti", "Ó Allah, concede-nos temor suficiente de Ti para que se erga entre nós e Tua desobediência, obediência suficiente para nos conduzir ao Teu Paraíso, e certeza suficiente para nos aliviar as desgraças deste mundo. Faze-nos desfrutar de nossa audição, nossa visão e nossa força enquanto nos mantiveres vivos, e faze disso para nós uma herança duradoura. Vinga-nos de quem nos faz mal, ajuda-nos contra nossos inimigos, não faças de nossa religião o lugar de nossa desgraça, não faças deste mundo nossa maior preocupação nem o limite de nosso conhecimento, e não coloques sobre nós quem não terá piedade de nós.", "Ao se levantar de uma assembleia — o Profeta ﷺ raramente se levantava sem fazer esta súplica.", "Uma súplica completa pelo bem da religião, deste mundo e do além.")
    )
}
